   UPDATE catalogue_produits SET nom=p->>'nom', marque='Atlantic', description=p->>'description',
    -- Un produit déjà chiffré ne doit pas repasser « prix à renseigner ».
    caracteristiques=((COALESCE(caracteristiques,'{}'::jsonb) - 'prix_source' - 'source_import' - 'source_date' - 'source_tarifs') || COALESCE(p->'caracteristiques','{}'::jsonb))
      - CASE WHEN COALESCE(prix_unitaire_ht,0) > 0 THEN 'prix_a_renseigner' ELSE '' END,
    fiche_cee='BAR-TH-171', eligible_cee=COALESCE((p->>'eligible_cee')::boolean,eligible_cee),
    actif=true, public_cible='particulier', catalogue_groupe='particulier'
   WHERE id=v_id;
   -- Prix, TVA et forfaits existants ne sont volontairement pas écrasés.
  END IF;
  v_id := NULL;
 END LOOP;
END $$;
